   box(x,.62,z,1.75,1.24,.68,wood);
   for(const offset of [-.72,.72])box(x+offset,.64,z-.38,.12,1.18,.12,plank);
   for(let i=0;i<3;i++)box(x,.20+i*.41,z-.4,1.7,.095,.12,plank);
   limb([x-.7,.19,z-.46],[x+.68,1.12,z-.46],.06,edge);ps3Crate(x,z);
