 for(let i=0;i<chips;i++){const px=c.x+fxrng.float(-.60,.60),py=fxrng.float(.35,1.65);debris.push({p:[px,py,c.z],v:[fxrng.float(-2.6,2.6),fxrng.float(1.1,3.5),fxrng.float(-2.8,2.8)],spin:fxrng.float(-8,8),angle:0,life:6,sz:fxrng.float(.1,.33),color:[.43,.30,.18]})}
