 if(room.plan?.length)return room.plan.map(q=>({type:q.type,x:rng.float(q.xMin,q.xMax),d:rng.float(q.dMin,q.dMax)}));
 // Position varies each run; challenge categories and one-at-a-time sequence fights stay fair.
