   const a=spawnOffscreen('runner',1,rng.next()<.5?-1:1,rng.float(10,13));
   a.isOpeningWave=true;openingLoneReinforcementDone=true;
   const enc=run.encounters.at(-1);if(enc)enc.types.push('runner');
