  const x=fxrng.float(-1.12,1.12),y=fxrng.float(.13,1.6),z=w.z+fxrng.float(-.35,.35);
  debris.push({p:[x,y,z],v:[fxrng.float(-2,2),fxrng.float(.6,3.5),fxrng.float(-1.5,1.5)],spin:fxrng.float(-6,6),angle:0,life:5,sz:fxrng.float(.10,.30)});
  const r={x,y:fxrng.float(.1,.27),z:z+fxrng.float(-.6,.6),w:fxrng.float(.22,.65),h:fxrng.float(.14,.45),d:fxrng.float(.18,.5),rot:fxrng.float(-.5,.5),color:[.41,.36,.30]};
  w.rubble.push(r);rubbleBlocks.push(r);
