 roomReinforcements=[];roomOverlapAt=Infinity;roomAmbushPending=0;roomAmbushAt=Infinity;
 openingGroupsSpawned=3;openingNextAt=Infinity;openingRetreatAt=Infinity;
 const room=RAIL_ROOMS[waveIndex-1],plan=railPlan(waveIndex-1);
 // Previous attackers should never leak into the next independent encounter.
 // Defeated ragdolls remain for their short settling animation until the rail departs.
