 // Rail encounters stage every initial threat well inside the camera frame.  The
 // roughly 32 CSS-pixel guard band is comfortably more than 1/3 inch on common
 // desktop displays, while subsequent movement is still free to use the whole room.
 const safeHalfWidth=plan.length>=4?1.45:plan.length===3?1.25:1.05;
 for(let i=0;i<plan.length;i++){
  const normalized=plan.length===1?0:(i/(plan.length-1)*2-1);
  const type=plan[i],offset=clamp(normalized*safeHalfWidth+rng.float(-.08,.08),-1.5,1.5);
  const zDistance=type==='sequence'?10.2:rng.float(9.4,11.7);
  const a=enemy(type,offset,cam.z-zDistance,[1,2,3]);
  a.room=waveIndex;a.entryActive=false;a.entryDelay=.32+i*.10;
  a.entryTargetX=offset;a.spawnX=offset;a.x=offset;a.cover=null;
  a.railSafeStart=true;a.railSafeAge=0;
  // The third stage deliberately tests a sudden change from standing to fast crawling.
  a.panicEligible=false;
 }
 run.events.push({t:+elapsed.toFixed(3),kind:'rail-room-enter',room:waveIndex,name:room.name,types:plan.slice(),intensity:difficultyNow});
 run.encounters.push({index:waveIndex,room:room.name,startedAt:elapsed,types:plan.slice(),shotsAtStart:run.shots,hitsAtStart:run.hits,firstShotLatency:null,completedAt:null,healthAtStart:run.healthLost,intensityAtStart:difficultyNow});
 $('checkpoint').textContent='RAIL '+waveIndex+'/5 · '+room.name;
