 run.encounters.push({index:waveIndex,room:room.name,startedAt:elapsed,types:wave.map(w=>w.type),shotsAtStart:run.shots,hitsAtStart:run.hits,firstShotLatency:null,completedAt:null,healthAtStart:run.healthLost,intensityAtStart:difficultyNow});
