function showHospitalOverlay(message,small=''){if(mode!=='hospital')return;$('hospitalOverlay').style.display='block';$('hospitalMessage').textContent=message;$('hospitalCounter').textContent=small}
function beginEvade(){
  if(state!=='playing'||mode!=='hospital')return;
  if(hospitalPhase==='front'&&waveIndex>=1&&waveIndex<5){
    // Player-initiated turn does not require a room clear. Do not award a
    // normal performance/clear bonus for an encounter left unfinished.
    const w=run.encounters.at(-1);
    if(w&&!w.completedAt){w.completedAt=elapsed;w.earlyRetreat=true;w.activeThreatsAtRetreat=actors.filter(a=>!a.done&&!a.ragdoll).length;}
    roomReinforcements=[];roomOverlapAt=Infinity;
    roomAmbushPending=0;roomAmbushAt=Infinity;
    clearHoldUntil=null;
    run.events.push({t:+elapsed.toFixed(3),kind:'manual-early-retreat',room:waveIndex,activeThreats:actors.filter(a=>!a.done&&!a.ragdoll).length});
    startWallRetreat();
  }
  if(!hospitalEvadeReady||hospitalPhase!=='await-retreat')return;
 hospitalEvadeReady=false;hospitalAwaitingEvade=false;
 breachHitsDone=0;breachShotTimes=[];breachWallMarks=[];breachStarted=elapsed;
 breachWallZ=currentWall().z;gun.reloading=0;
 const final=waveIndex===4;
 hospitalPhase=final?'surprise-wait':'breach';surpriseAge=0;surpriseSpawned=false;
 hospitalPhaseLog.push({at:+elapsed.toFixed(3),phase:final?'surprise-wait':'breach',room:waveIndex});
 run.roomRetreats.push({from:waveIndex,at:+elapsed.toFixed(3),enemyBreach:final,wallShots:0});
 if(final){showHospitalOverlay('FINAL WALL · BREAK THROUGH','Something is moving on the other side…');showNote('TURN AROUND · LAST WALL','#e6c48d')}
 else{showHospitalOverlay('REAR WALL · EIGHT SHOTS',`0 / ${cfg.breachHits} · PURSUERS STILL APPROACHING`);showNote('TURN AROUND · BREACH BEFORE THEY REACH YOU','#e6c48d')}
 snd('turn_wall');
}
function shootWall(d){
 const w=currentWall();if(!w||w.open)return false;
 const z=w.z,t=(z-cam.z)/d[2];if(t<=0)return false;
 const x=cam.x+d[0]*t,y=cam.y+d[1]*t;
 if(Math.abs(x)>.95||y<.72||y>2.55)return false;
 breachHitsDone++;breachShotTimes.push(elapsed);run.hits++;run.objectHits++;w.marks.push([x,y,z]);
 gun.score+=Math.round(85*difficultyNow);if(run.roomRetreats.length)run.roomRetreats.at(-1).wallShots=breachHitsDone;
 for(let i=0;i<4;i++)burstParticle([x,y,z-.04],[.55,.50,.43],'fragment',.27);
 showHospitalOverlay('BREAK THE CENTRE OF THE WALL',`${breachHitsDone} / ${cfg.breachHits} hits · attackers approaching from behind`);
 run.events.push({t:+elapsed.toFixed(3),kind:'wall-hit',room:waveIndex,step:breachHitsDone});
 if(breachHitsDone>=cfg.breachHits){
  const times=breachShotTimes;let peak=0;for(let i=0;i<times.length;i++){let j=i;while(j<times.length&&times[j]-times[i]<=1)j++;peak=Math.max(peak,j-i)}
  const record={room:waveIndex,shots:times.slice(),duration:+(elapsed-breachStarted).toFixed(3),peak1s:peak,firstToLast:+(times.at(-1)-times[0]).toFixed(3)};
  run.breach=record;if(run.roomRetreats.length)Object.assign(run.roomRetreats.at(-1),{duration:record.duration,peak1s:peak});
  run.events.push({t:+elapsed.toFixed(3),kind:'breach-complete',room:waveIndex,duration:record.duration,peak1s:peak});
  collapseWall(w);hospitalPhase='collapse';breachCollapseAge=0;gun.score+=Math.round(400*difficultyNow);
  showHospitalOverlay('WALL COLLAPSING','Keep moving · defend from the next room');snd('armor');
 }
 return true;
}
function renderHospital(){
 if(mode!=='hospital'&&mode!=='rail')return;
 const spacing=cfg.roomSpacing;
 // Five physically persistent and visually distinct enclosed hospital wards.
 const themes=[
  {wall:[.32,.37,.34],wood:[.45,.32,.22],accent:[.27,.52,.43],kind:'ENTRY WARD'},
  {wall:[.39,.38,.33],wood:[.48,.35,.24],accent:[.63,.47,.20],kind:'WINDOW WARD'},
  {wall:[.28,.34,.39],wood:[.39,.34,.32],accent:[.30,.56,.67],kind:'ARMORED WARD'},
  {wall:[.38,.31,.35],wood:[.46,.32,.30],accent:[.61,.30,.39],kind:'TREATMENT WARD'},
  {wall:[.30,.29,.33],wood:[.40,.31,.25],accent:[.60,.47,.23],kind:'FINAL WARD'}];
 const visible=Math.max(0,waveIndex-1);
 for(let i=Math.max(0,visible-1);i<Math.min(5,visible+2);i++){
  const z=i*spacing,t=themes[i];
  if(Math.abs(z-cam.z)>21)continue;
  if(i===0){
    // Camera is inside the entrance threshold, aiming OUT at the approach.
    // Open sky above the exterior and a hospital doorway framing the view.
    box(0,-.21,z,10.2,.4,spacing-.07,[.22,.23,.20]);
    for(const x of [-4.23,4.23]){
      box(x,1.78,z-2.55,1.18,3.55,1.0,[.47,.39,.29]);
      box(x,1.07,z-3.14,.65,1.95,.25,[.30,.26,.21]);
      box(x,3.36,z-2.50,1.25,.21,1.05,[.63,.48,.27]);
    }
    box(0,3.56,z-2.53,7.35,.42,1.2,[.43,.34,.25]);
    box(0,3.12,z-2.55,4.6,.29,.18,[.59,.46,.30]);
    for(let k=0;k<4;k++){
      const zz=z-7.9-k*4.3;
      box(0,-.15,zz,14,.24,4.25,[.21,.24,.20]);
      box(-5.8,.55,zz,1.3,1.1,.32,[.33,.32,.25]);
      box(5.8,.55,zz,1.3,1.1,.32,[.34,.32,.25]);
      for(const x of [-7.3,7.3])box(x,1.3,zz+1.2,.6,2.6,.6,[.26,.30,.25]);
    }
    box(0,4.25,z+3.52,10.2,.36,3.05,[.23,.22,.20]);
    continue;
  }
  box(0,-.21,z,10.2,.4,spacing-.07,[.22,.23,.20]);box(0,3.75,z,10.2,.30,spacing-.09,[.22,.23,.22]);
  box(-5.06,1.76,z,.3,3.75,spacing-.05,t.wall);box(5.06,1.76,z,.3,3.75,spacing-.05,t.wall);
  for(const dz of [-3.3,3.3]){box(-4.91,2,z+dz,.12,3.3,.12,t.wood);box(4.91,2,z+dz,.12,3.3,.12,t.wood)}
  box(0,3.47,z,5.7,.12,.12,t.accent,1);
  if(i===1){ // Framed windows and timber sills
    for(const x of [-4.9,4.9])for(const dz of [-2.1,1.8]){
       box(x,2.17,z+dz,.13,1.25,1.2,[.13,.17,.19]);box(x,2.8,z+dz,.17,.10,1.27,t.wood);box(x,1.54,z+dz,.19,.12,1.27,t.wood);
    }
  }else if(i===2){ // Armored ward's medicine cupboards and steel shelving
    for(const dz of [-2.8,.5,2.7]){box(-4.65,1.6,z+dz,.60,2.5,1.25,[.27,.33,.36]);box(-4.25,1.9,z+dz,.14,.07,1.1,t.accent)}
  }else if(i===3){ // Treatment room partitions and overhead emergency panels
    for(const dz of [-2.9,2.65]){box(4.4,1.4,z+dz,.13,2.7,1.45,[.59,.57,.51]);box(4.28,2.6,z+dz,.06,.12,1.55,t.accent)}
  }else if(i===4){for(const x of [-3.6,3.6]){box(x,2,z,.14,3.2,3.0,t.wood);box(x,3.45,z,.26,.17,3.0,t.accent)}}
  // One seeded smoke room receives denser volumetric-distance fog and moving haze bands.
  if(i+1===smokeRoomIndex){
     // Fire sources at both sides of the ward, flickering upward through the smoke.
     for(let f=0;f<4;f++){
       const fx=f%2===0?-4.25:4.25, fz=z-3.1+Math.floor(f/2)*5.6;
       const flick=.74+.26*Math.sin(globalTime*12+f*2.5);
       box(fx,.12,fz,.73,.22,.76,[.20,.16,.13]);
       for(let q=0;q<4;q++){
         const yy=.24+q*.23,rr=.32*(1-q*.17)*flick;
         orb([fx+.14*Math.sin(globalTime*6+f+q*2),yy,fz+.09*Math.sin(globalTime*7+f-q)],rr,q<2?[1,.22,.035]:[1,.47,.06],2.7);
       }
       box(fx,.07,fz,.85,.08,.93,[.68,.22,.06],1.8);
     }
     for(let k=0;k<7;k++){
     const zz=z-4+k*1.37,xx=Math.sin(globalTime*.25+k*1.7)*1.6;
     box(xx,2.4+Math.sin(globalTime*.22+k)*.13,zz,2.3,.035,.055,[.38,.43,.43],.15);
  }}
 }
 for(const prop of sceneProps)if(!prop.broken&&Math.abs(cam.z-prop.z)<19)renderCover(prop);
 // The main barriers have two permanent side sections and one breakable centre panel.
 for(const w of roomWalls){if(mode==='rail')continue;if(Math.abs(cam.z-w.z)>17)continue;
  const col=[.43,.38,.32];
  for(const x of [-3.05,3.05])box(x,1.77,w.z,3.9,3.53,.42,col);
  box(0,3.48,w.z,2.2,.2,.44,[.28,.28,.26]);
  if(!w.open){box(0,1.72,w.z,2.18,3.36,.41,[.48,.43,.36]);
    // Impact marks accumulate before the eighth shot; no holes until collapse.
    for(let i=0;i<w.marks.length;i++){
      const q=w.marks[i],near=w.z-Math.sign(w.z-cam.z)*.23;
      orb([q[0],q[1],near],.053,[.10,.09,.08]);
      for(let j=0;j<5;j++){
        const a=j*1.256+i*.47,len=.11+i*.012;
        limb([q[0],q[1],near],[q[0]+Math.cos(a)*len,q[1]+Math.sin(a)*len,near],.008,[.14,.12,.10]);
      }
    }
  }
  else for(const r of w.rubble)box(r.x,r.y,r.z,r.w,r.h,r.d,r.color,.03,r.rot);
 }
}

