function beginPlayerShotStreak(){
 if(!run)return;
 const previous=run.hitStreakCurrent||0;
 run.hitStreakPrevious=previous;
 run.hitStreakCurrent=0;
 if(previous>0)run.hitStreakBreaks++;
 run.hitStreakLastEventIndex=run.events.length;
 run.events.push({t:+elapsed.toFixed(3),kind:'hit-streak-shot',scene:mode==='custom'?customSceneIndex+1:waveIndex,shot:run.shots,liveTargetHit:false,streak:0,best:run.hitStreakBest,reason:'no-live-target'});
}
function creditPlayerLiveHitStreak(){
 if(!run)return;
 run.hitStreakCurrent=(run.hitStreakPrevious||0)+1;
 run.hitStreakBest=Math.max(run.hitStreakBest||0,run.hitStreakCurrent);
 run.hitStreakQualifyingHits++;
 if((run.hitStreakPrevious||0)>0)run.hitStreakBreaks=Math.max(0,run.hitStreakBreaks-1);
 const event=run.events[run.hitStreakLastEventIndex];
 if(event&&event.kind==='hit-streak-shot'){
  Object.assign(event,{liveTargetHit:true,streak:run.hitStreakCurrent,best:run.hitStreakBest,reason:'living-enemy'});
 }
}
