// A valid Motion Studio file may be a single scene, the whole exported sequence,
// or an array of scenes. Import never executes code supplied by the JSON file.
function weaponChoice(t){
 const value=t?.weapon;
 return {type:['none','baton','cleaver','gun'].includes(value?.type)?value.type:(t?.enemyType==='shooter'?'gun':'none'),hand:value?.hand==='left'?'left':'right'};
}
function customWeapon(e){return e?.customTarget?weaponChoice(e.customTarget):null;}
function customDepthOrder(v,at){
 let order=Number.isInteger(v?.depthOrder)?clamp(v.depthOrder,-9,9):0;
 if(Number.isFinite(at))for(const k of v?.depthKeys||[]){if(k.t>at+1e-6)break;order=k.order;}
 return order;
}
function customDepthOrderValid(v){return v===undefined||(Number.isInteger(v)&&v>=-9&&v<=9);}
function customDepthKeysValid(keys,duration){
 return keys===undefined||(Array.isArray(keys)&&keys.length<=240&&keys.every((k,i)=>
  k&&Number.isFinite(k.t)&&k.t>=0&&k.t<=duration&&Number.isInteger(k.order)&&k.order>=-9&&k.order<=9&&
  (!i||k.t-keys[i-1].t>=.001)));
}
function customObjectShatterHits(o){
 if(o?.westernBuilding)return 99;
 if(o?.shatterable)return 1;
 const ph=o?.transformOnHits;
 if(ph&&Number.isInteger(ph.hits)&&ph.hits>=1&&ph.hits<=99)return ph.hits;
 return Number.isInteger(o?.shatterHits)?clamp(o.shatterHits,1,99):(o?.westernBuilding?20:1);
}
function customPhaseObjectVisible(o,s){
 if(!o||!s)return false;
 const sources=(s.objects||[]).filter(q=>q?.transformOnHits?.targetObjectId===o.id);
 return !sources.length||customActivatedPhaseObjects.has(o.id);
}


// CUSTOM JSON PLAYER COVER v16: uses the SAME authored object ID, hit limit,
// and hold key as the Studio 2D tester. Native Hospital/Rail remain unchanged.
let customHangmanCutAt=-Infinity;
