   if(t.looseKeys!==undefined&&(!Array.isArray(t.looseKeys)||t.looseKeys.length>1200||!t.looseKeys.every(k=>k&&Number.isFinite(k.t)&&k.joints&&typeof k.joints==='object'&&Object.entries(k.joints).every(([name,xy])=>STUDIO_LOOSE_NAMES.includes(name)&&Array.isArray(xy)&&xy.length===2&&xy.every(n=>Number.isFinite(n)&&Math.abs(n)<=3.01)))))throw Error('Scene '+(i+1)+' has invalid Loose Mode poses.');
