    const spec=stage.duel||{};
    const base=Math.max(200,Number(spec.drawWindowMs)||2100);
    const limit=tier==='lightning'
      ?Math.max(150,Number(spec.lightningWindowMs)||[800,725,650,575,525,475,425,375][Math.min(7,idx)])
      :Math.round(base*(DUEL_PACES[tier]?.multiplier||1));
