const duelSetupStyle=document.createElement('style');duelSetupStyle.textContent=`#duelSetup .duelRootMenuBtn{position:absolute;top:5px;left:5px;width:165px;height:30px;box-sizing:border-box;padding:4px 8px;font:700 12px Arial;letter-spacing:1px;text-align:center;background:#5b391f;border:1px solid #b88c60;color:#ffe3b5;z-index:1}#duelSetup .duelSetupCard{position:relative;max-width:590px;width:100%;max-height:95vh;overflow:auto;padding:25px;background:#211912;border:2px solid #c7a470;box-shadow:0 10px 45px #000}#duelSetup h2{font-size:22px;color:#f4e3c1}#duelSetup small{color:#cda978;font:11px Arial;letter-spacing:1px}#duelSetup h3{font:800 12px Arial;letter-spacing:2px;margin-top:17px}#duelPlayerInput{padding:12px;background:#0c1015;color:#fff;border:1px solid #c7a470;width:100%;box-sizing:border-box;font-size:18px}#duelSetup .duelPaces{display:grid;grid-template-columns:1fr 1fr;gap:8px}#duelSetup .duelPaces label{display:grid;grid-template-columns:20px 1fr;gap:1px 6px;border:1px solid #765d43;padding:10px;background:#12110d;cursor:pointer}#duelSetup .duelPaces input{grid-row:1/3;align-self:center}#duelSetup .duelPaces small{grid-column:2;letter-spacing:0}#duelSetup .duelPaceHead{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:4px 7px}#duelSetup .duelPaceTarget{font:700 10px Arial;letter-spacing:0;color:#e0ba7b;white-space:nowrap}#duelSetup .duelSetupActions{display:flex;justify-content:space-between;gap:9px;margin-top:15px}#duelSetup button{padding:10px 17px;background:#49331d;color:#ffdfb5;border:1px solid #aa8057;cursor:pointer}#duelSetupBegin{background:#825229!important}#duelSetup .duelSetupTopBar{display:flex;gap:10px;justify-content:space-between;align-items:center;flex-wrap:wrap}#duelSetup .duelSetupTopNav{display:flex;gap:5px}#duelSetup .duelSetupTopNav button{font:700 10px Arial;letter-spacing:1px;padding:8px 10px;background:#291b0f;border:1px solid #775f43;white-space:nowrap}#duelSetup .ddNamePointerRow{display:flex;align-items:stretch;gap:7px}#duelSetup .ddNamePointerRow #duelPlayerInput{flex:1;min-width:0}#duelSetup #ddPointerToggle{width:36px;min-width:36px;max-height:46px;box-sizing:border-box;padding:3px!important;font:bold 20px Arial!important;text-align:center;background:#342416;color:#ffe4bd}#duelSetup #ddPointerToggle[aria-expanded="true"]{outline:2px solid #e3b87e}#duelSetup .ddPointerPanel{margin-top:8px;padding:10px;background:#15110d;border:1px solid #846747;display:grid;grid-template-columns:1fr;gap:7px;color:#e4c9a4;font:700 11px Arial}#duelSetup .ddPointerPanel[hidden]{display:none!important}#duelSetup .ddPointerPanel label{display:flex;align-items:center;gap:9px;min-height:29px;cursor:pointer}#duelSetup .ddPointerPanel label input[type=radio]{accent-color:#e1b77d}#duelSetup .ddPointerPanel input[type=color]{width:37px;height:27px;padding:1px;margin-left:auto;cursor:pointer;background:#24180f;border:1px solid #836344}#duelSetup .ddPointerPanel .ddPointerSample{font:bold 18px Arial;width:22px;text-align:center;color:#ff0000}#duelSetup .ddPointerPanel strong{letter-spacing:1px}#duelSetup .ddPointerPanel small{letter-spacing:0;font:11px Arial;color:#bca98e}#duelSetup button[disabled]{opacity:.48;cursor:not-allowed}#duelSetup .duelAboutOverlay{position:absolute;inset:0;background:#080705ec;display:flex;align-items:center;justify-content:center;padding:14px;z-index:4;overflow:auto}#duelSetup .duelAboutOverlay[hidden]{display:none!important}#duelSetup .duelAboutCard{position:relative;background:#211912;border:2px solid #c7a470;box-shadow:0 10px 45px #000;padding:24px;max-width:610px;width:100%;max-height:88vh;overflow-y:auto;box-sizing:border-box}#duelSetup .duelAboutCard h2{margin:2px 0 14px;padding-right:38px}#duelSetup .duelAboutCard h3{margin:20px 0 8px;color:#f2d6a4}#duelSetup .duelAboutCard p{line-height:1.55;margin:9px 0}#duelSetup .duelAboutCard ul{padding-left:21px;line-height:1.55}#duelSetup .duelAboutCard li{margin:10px 0}#duelSetup .duelAboutCard a{color:#ffdca9;text-decoration:underline}#duelSetup .duelAboutCard .duelAboutNote{font-size:12px;color:#d0b992;border-top:1px solid #75593b;padding-top:12px}#duelSetup .duelAboutX{position:absolute;right:14px;top:12px;padding:6px 11px}#duelSetup .duelAboutFooter{display:flex;justify-content:flex-end;margin-top:20px}@media(max-width:550px){#duelSetup .duelPaces{grid-template-columns:1fr}#duelSetup .duelSetupTopNav button{padding:7px}}`;
