const ddPointerVisualStyle=document.createElement('style');
ddPointerVisualStyle.textContent=`body.ddPointerNative #world{cursor:default!important}body.ddPointerNative:not(.ddSindenSafeActive) #crosshair{display:none!important}body.ddPointerPlus #crosshair:before,body.ddPointerPlus #crosshair:after{background:var(--dd-pointer-color,#ff0000)!important}body.ddPointerPlus #crosshair .pinpoint{background:var(--dd-pointer-color,#ff0000)!important}body.ddPointerDot #crosshair:before,body.ddPointerDot #crosshair:after{display:none!important}body.ddPointerDot #crosshair .pinpoint{left:9px;top:9px;width:5px;height:5px;background:var(--dd-pointer-color,#ff0000)!important;border:0;border-radius:50%;box-shadow:0 0 1px #000,0 0 3px #000}body.ddPointerNative.ddSindenSafeActive #world{cursor:none!important}body.ddPointerNative.ddSindenSafeActive #crosshair{display:block!important}`;
document.head.append(ddPointerVisualStyle);
const DDPointerChoice=(()=>{
 const KEY='dmd-pointer-display-v1';
 const validColor=s=>/^#[0-9a-f]{6}$/i.test(s||'');
 const pref={kind:'plus',plus:'#ff0000',dot:'#ff0000'};
 try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&['native','plus','dot'].includes(s.kind))pref.kind=s.kind;if(s&&validColor(s.plus))pref.plus=s.plus.toLowerCase()==='#f2e7d0'?'#ff0000':s.plus;if(s&&validColor(s.dot))pref.dot=s.dot.toLowerCase()==='#f2e7d0'?'#ff0000':s.dot;}catch(_){ }
 const panel=document.getElementById('ddPointerPanel'),button=document.getElementById('ddPointerToggle');
 function draw(){document.body.classList.toggle('ddPointerNative',pref.kind==='native');document.body.classList.toggle('ddPointerPlus',pref.kind==='plus');document.body.classList.toggle('ddPointerDot',pref.kind==='dot');document.documentElement.style.setProperty('--dd-pointer-color',pref.kind==='dot'?pref.dot:pref.plus);button.textContent=pref.kind==='native'?'↖':pref.kind==='dot'?'•':'+';button.style.color=pref.kind==='dot'?pref.dot:pref.kind==='plus'?pref.plus:'#ffe4bd';for(const input of panel.querySelectorAll('input[name="ddPointerKind"]'))input.checked=input.value===pref.kind;document.getElementById('ddPointerPlusColor').value=pref.plus;document.getElementById('ddPointerDotColor').value=pref.dot;}
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(pref));}catch(_){}draw();};
 button.addEventListener('click',()=>{panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));});
 for(const input of panel.querySelectorAll('input[name="ddPointerKind"]'))input.addEventListener('change',()=>{if(input.checked){pref.kind=input.value;save();}});
 for(const [field,kind] of [['ddPointerPlusColor','plus'],['ddPointerDotColor','dot']])document.getElementById(field).addEventListener('input',e=>{if(validColor(e.target.value)){pref[kind]=e.target.value;pref.kind=kind;save();}});
 draw();return {get:()=>({...pref})};
})();
for(const [id,delta] of [['ddSindenCountMinus',-1],['ddSindenCountPlus',1]]){
 const b=document.getElementById(id);if(b)b.onclick=()=>ddSindenCountApply(ddSindenCountdownSeconds+delta);
}
const ddCountInput=document.getElementById('ddSindenCountSeconds');if(ddCountInput)ddCountInput.onchange=()=>ddSindenCountApply(ddCountInput.value);
for(const [id,delta] of [['ddSindenThickMinus',-2],['ddSindenThickPlus',2]]){
 const btn=document.getElementById(id);if(btn)btn.onclick=()=>ddSindenThicknessApply(ddSindenBorderThickness+delta);
}
const ddSindenPxInput=document.getElementById('ddSindenBorderPx');if(ddSindenPxInput){
 ddSindenPxInput.onchange=()=>ddSindenThicknessApply(ddSindenPxInput.value);
}
// Mercy's End · device-neutral controls. All gameplay actions reuse the original fire/reload/fullscreen functions.
// Controls are presentation/input state only, never recorded as a new ghost timeline event.
const DDControlBindings=(()=>{
 const KEY='dead-mans-draw-inputs-v1';
 const defaults={
  shoot:{mouse:'Mouse0',keyboard:'Space',gamepad:'Pad7'},
  reload:{mouse:'Mouse2',keyboard:'KeyR',gamepad:'Pad2'},
  fullscreen:{mouse:null,keyboard:'KeyF',gamepad:'Pad9'}
 };
 const names={shoot:'SHOOT',reload:'RELOAD',fullscreen:'FULLSCREEN'};
 const devices=['mouse','keyboard','gamepad'];
 let mapping=JSON.parse(JSON.stringify(defaults));
 const valid=(type,v)=>v===null||typeof v==='string'&&v.length<40&&(
  type==='mouse'? /^Mouse[0-4]$/.test(v)||v==='WheelUp'||v==='WheelDown':
  type==='keyboard'? /^(?:[A-Za-z0-9]{1,24}|F(?:[1-9]|1[0-2]))$/.test(v):
  /^Pad(?:[0-9]|[12][0-9]|3[01])$/.test(v));
 try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw){
   for(const action of Object.keys(defaults))for(const device of devices)
     if(Object.hasOwn(raw[action]||{},device)&&valid(device,raw[action][device]))mapping[action][device]=raw[action][device];
 }}catch(_){}
 let capture=null,gamepadPrev=new Map(),lastTick=performance.now(),swallowCapturedClick=false;
 const panel=document.createElement('div');panel.id='ddBindPanel';panel.hidden=true;
 panel.innerHTML=`<div class="ddBindCard" role="dialog" aria-modal="true" aria-label="Bind Controls">
  <div class="ddBindHeader"><h2>BIND CONTROLS</h2><button type="button" id="ddBindClose" aria-label="Close controls">✕</button></div>
  <p>Choose a binding, then press the desired key, mouse button, wheel direction, or gamepad button.</p>
  <div class="ddBindGrid"><span>ACTION</span><span>MOUSE</span><span>KEYBOARD</span><span>CONTROLLER</span>
  ${Object.keys(names).map(a=>`<strong>${names[a]}</strong>${devices.map(d=>`<button type="button" data-dd-action="${a}" data-dd-device="${d}"></button>`).join('')}`).join('')}
  </div><p id="ddBindHint" aria-live="polite">Gamepad: right stick aims · any standard gamepad button can be assigned. Escape cancels assignment.</p>
  <div class="ddBindFooter"><button type="button" id="ddBindReset">RESET DEFAULTS</button><button type="button" id="ddBindDone">DONE</button></div>
 </div>`;
 const style=document.createElement('style');style.textContent=`
 #ddBindPanel[hidden]{display:none!important}#ddBindPanel{position:fixed;inset:0;z-index:2147482900;background:#080705ea;display:flex;align-items:center;justify-content:center;padding:18px;color:#f1dbb7;font-family:Georgia,serif}
 #ddBindPanel .ddBindCard{box-sizing:border-box;background:#211912;border:2px solid #c5a071;padding:22px;max-width:690px;width:100%;max-height:95vh;overflow:auto;box-shadow:0 14px 50px #000}
 #ddBindPanel .ddBindHeader,.ddBindFooter{display:flex;justify-content:space-between;align-items:center;gap:14px}#ddBindPanel h2{margin:0;color:#ffdeb2}
 #ddBindPanel p{font-size:13px;color:#d4b993;line-height:1.4}
 #ddBindPanel .ddBindGrid{display:grid;grid-template-columns:120px repeat(3,minmax(0,1fr));gap:7px;align-items:center}
 #ddBindPanel .ddBindGrid>span{font:700 11px Arial;text-align:center;color:#cca878}#ddBindPanel .ddBindGrid strong{font:700 13px Arial}
 #ddBindPanel button{padding:9px 8px;cursor:pointer;border:1px solid #a78058;background:#362418;color:#f7dab5;font:700 12px Arial;min-height:38px}
 #ddBindPanel button.active{border-color:#fff;background:#6b4320;color:#fff;outline:2px solid #c6a06f}
 #ddBindPanel button:focus-visible{outline:2px solid #fff;outline-offset:2px}
 #ddBindPanel .ddBindFooter{margin-top:20px}
 @media(max-width:550px){#ddBindPanel .ddBindGrid{grid-template-columns:70px repeat(3,minmax(0,1fr));gap:4px}#ddBindPanel button{padding:8px 3px;font-size:10px}#ddBindPanel .ddBindCard{padding:12px}}
 `;document.head.append(style);document.body.append(panel);
 const hint=panel.querySelector('#ddBindHint');
 const format=(device,v)=>v===null?'—':device==='mouse'?
  ({Mouse0:'Left click',Mouse1:'Middle',Mouse2:'Right click',Mouse3:'Mouse Back',Mouse4:'Mouse Forward',WheelUp:'Wheel ↑',WheelDown:'Wheel ↓'}[v]||v):
  device==='gamepad'?`Button ${Number(v.slice(3))}`:(v==='Space'?'Spacebar':v.replace(/^Key/,'').replace(/^Digit/,'').replace(/^Arrow/,'Arrow '));
 function save(){try{localStorage.setItem(KEY,JSON.stringify(mapping));}catch(_){}}
 function render(){for(const button of panel.querySelectorAll('[data-dd-action]')){
  const a=button.dataset.ddAction,d=button.dataset.ddDevice;
  button.textContent=capture?.button===button?'PRESS INPUT…':format(d,mapping[a][d]);
  button.classList.toggle('active',capture?.button===button);
  button.title=`${names[a]} · ${d}: ${format(d,mapping[a][d])}`;
 }}
 function setBinding(action,device,value){
  // One physical input cannot fire two different actions.
  for(const a of Object.keys(mapping))if(a!==action&&mapping[a][device]===value)mapping[a][device]=null;
  mapping[action][device]=value;capture=null;save();render();
  hint.textContent=`${names[action]}: ${format(device,value)} assigned. Changes are saved on this device.`;
 }
 const isOpen=()=>!panel.hidden;
 function close(){capture=null;panel.hidden=true;render();}
 function open(){panel.hidden=false;capture=null;hint.textContent='Select any control to rebind. Controller buttons require a connected gamepad.';render();panel.querySelector('#ddBindClose').focus();}
 panel.querySelector('#ddBindClose').onclick=close;panel.querySelector('#ddBindDone').onclick=close;
 panel.querySelector('#ddBindReset').onclick=()=>{mapping=JSON.parse(JSON.stringify(defaults));capture=null;save();render();hint.textContent='Original mouse, keyboard, and controller bindings restored.';};
 for(const b of panel.querySelectorAll('[data-dd-action]'))b.onclick=()=>{capture={action:b.dataset.ddAction,device:b.dataset.ddDevice,button:b};render();hint.textContent=`Waiting for ${capture.device} input for ${names[capture.action]}… (Esc cancels)`;};
 document.getElementById('duelBindControlsBtn').onclick=open;
 // Capture before the game or browser's other gameplay shortcuts see the input.
 window.addEventListener('keydown',e=>{if(!isOpen())return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(capture){capture=null;render();hint.textContent='Assignment cancelled.';}else close();return;}
  if(!capture){e.preventDefault();e.stopImmediatePropagation();return;}
  if(capture.device!=='keyboard')return;
  e.preventDefault();e.stopImmediatePropagation();setBinding(capture.action,'keyboard',e.code);
 },true);
 window.addEventListener('pointerdown',e=>{if(!isOpen()||!capture||capture.device!=='mouse')return;
  // The click that SELECTS a binding arrives before capture is armed; the NEXT pointerdown
  // can be anywhere, including the original 'PRESS INPUT' button itself.
  if(e.target.closest?.('#ddBindReset,#ddBindDone,#ddBindClose'))return;
  if(e.button<0||e.button>4)return;
  e.preventDefault();e.stopImmediatePropagation();swallowCapturedClick=true;setTimeout(()=>swallowCapturedClick=false,350);setBinding(capture.action,'mouse','Mouse'+e.button);
 },true);
 // Capture any button, including right-click, while waiting for mouse assignment.
 panel.addEventListener('pointerdown',e=>{if(!capture||capture.device!=='mouse')return;
  if(e.target.matches?.('[data-dd-action]')||e.target.closest?.('#ddBindReset,#ddBindDone,#ddBindClose'))return;
  e.preventDefault();e.stopPropagation();if(e.button>=0&&e.button<=4)setBinding(capture.action,'mouse','Mouse'+e.button);
 },true);
 window.addEventListener('click',e=>{if(swallowCapturedClick){swallowCapturedClick=false;e.preventDefault();e.stopImmediatePropagation();}},true);
panel.addEventListener('contextmenu',e=>e.preventDefault());
 window.addEventListener('wheel',e=>{if(!isOpen()||!capture||capture.device!=='mouse')return;
  e.preventDefault();e.stopImmediatePropagation();setBinding(capture.action,'mouse',e.deltaY<0?'WheelUp':'WheelDown');
 },{capture:true,passive:false});
 function actionFor(device,code){return Object.keys(names).find(action=>mapping[action][device]===code)||null;}
 function execute(action){if(DDCinematic.active){if(action==='shoot'&&DDCinematic.canSkip?.())DDCinematic.end();return;}
  if(action==='shoot')fire();else if(action==='reload')reload();else if(action==='fullscreen')fullscreen();
 }
 function key(e){if(isOpen())return true;const el=document.activeElement;
  if(el?.matches?.('input,textarea,select,[contenteditable]'))return false;
  const action=actionFor('keyboard',e.code);if(!action)return false;
  if(e.repeat){e.preventDefault();return true;}
  e.preventDefault();execute(action);return true;
 }
 function mouse(e){if(isOpen())return false;const action=actionFor('mouse','Mouse'+e.button);if(!action)return false;
  e.preventDefault();execute(action);return true;
 }
 function wheel(e){if(isOpen())return false;const action=actionFor('mouse',e.deltaY<0?'WheelUp':'WheelDown');if(!action)return false;
  e.preventDefault();execute(action);return true;
 }
 function tick(updateAim){
  const now=performance.now(),delta=Math.min(.05,Math.max(0,(now-lastTick)/1000));lastTick=now;
  let pads=[];try{pads=Array.from(navigator.getGamepads?.()||[]).filter(Boolean);}catch(_){}
  const current=new Map();
  for(const gp of pads){
   gp.buttons.forEach((v,i)=>{const down=!!(v?.pressed||v?.value>.55),code=`${gp.index}:${i}`;
    current.set(code,down);
    if(down&&!gamepadPrev.get(code)){
     if(isOpen()&&capture?.device==='gamepad'){setBinding(capture.action,'gamepad','Pad'+i);}
     else if(!isOpen()){const action=actionFor('gamepad','Pad'+i);if(action)execute(action);}
    }
   });
   if(state==='playing'&&!isOpen()&&!DDCinematic.active){
    // Right thumb stick aims; gamepads with only two axes can use their primary stick.
    const ax=gp.axes.length>=4?2:0,ay=gp.axes.length>=4?3:1;
    const x=gp.axes[ax]||0,y=gp.axes[ay]||0;
    if(Math.hypot(x,y)>.19&&typeof updateAim==='function')updateAim({clientX:Math.max(0,Math.min(innerWidth,aim.x+x*850*delta)),clientY:Math.max(0,Math.min(innerHeight,aim.y+y*850*delta))});
   }
  }
  gamepadPrev=current;
 }
 // Gamepad button edges are polled, not tied to video or duel time.
 const gamepadLoop=()=>{tick(typeof updateAim==='undefined'?null:updateAim);requestAnimationFrame(gamepadLoop);};
 requestAnimationFrame(gamepadLoop);
 render();
 return {open,close,key,mouse,wheel,tick,isOpen};
})();
