  const d=await r.json();
  if(!r.ok){if(isRefresh){authMem=null;try{localStorage.removeItem(authStore)}catch(_){};return anonymousToken()}
   throw Error(d?.msg||d?.error_description||d?.message||'Enable anonymous sign-ins in Supabase Authentication > Providers');}
  if(!d.access_token||!d.refresh_token)throw Error('Anonymous sign-in did not return a session. Enable Anonymous Sign-Ins in Supabase.');
