     const item=make('div',undefined,'border:1px solid #654a2c;background:#17100c;padding:10px;margin:7px 0');
     item.append(make('div','#'+r.rank+' '+r.player_name+' · '+(r.success?'SUCCESS':'FAILED')+' · '+r.difficulty.toUpperCase()+' · AVG WIN '+(r.average_draw_ms??'—')+'ms · FASTEST WIN '+(r.fastest_draw_ms??'—')+'ms'));
