// Sinden scene variants: a circular lower-screen holster safe spot.
// This is an AIM latch, not OS pointer-lock or mouse warping. Real offscreen
// Sinden events cannot throw the game cursor to (0,0) while the latch holds.
const ddSindenSafeCircle=document.createElement('div');
ddSindenSafeCircle.id='ddSindenSafeCircle';
ddSindenSafeCircle.setAttribute('aria-hidden','true');
ddSindenSafeCircle.textContent='SAFE';
ddSindenSafeCircle.style.cssText='display:none;position:fixed;left:50%;top:88%;transform:translate(-50%,-50%);width:clamp(84px,16vmin,140px);aspect-ratio:1;border:4px solid #f3d49d;border-radius:50%;box-sizing:border-box;background:radial-gradient(circle,rgba(28,21,14,.42),rgba(28,21,14,.12));box-shadow:0 0 0 4px #0005,0 0 20px #ffdb9680,inset 0 0 14px #0009;z-index:18;pointer-events:none;color:#fff1cf;font:800 11px Arial,sans-serif;letter-spacing:1px;align-items:center;justify-content:center;text-shadow:0 1px 3px #000';
document.body.appendChild(ddSindenSafeCircle);
let ddSindenSafeLocked=false,ddSindenSafeAwaitReentry=false,ddSindenSafeScene=null,ddSindenSafeSceneStart=-Infinity,ddSindenSafeCarry=false;
let ddSindenCountdownSeconds=10,ddSindenGate=null;
try{const remembered=localStorage.getItem('dd-sinden-start-countdown');if(remembered!==null)ddSindenCountdownSeconds=Math.max(0,Math.min(60,Math.round(Number(remembered)||0)));}catch(_){}
function ddSindenCountApply(value){
 ddSindenCountdownSeconds=Math.max(0,Math.min(60,Math.round(Number(value)||0)));
 const input=document.getElementById('ddSindenCountSeconds');if(input)input.value=String(ddSindenCountdownSeconds);
 try{localStorage.setItem('dd-sinden-start-countdown',String(ddSindenCountdownSeconds));}catch(_){}
}
function ddSindenCountMenu(){
 // The setup UI may open before the nine-scene pack is imported or restored.
 // Never hide the saved referee timer based on transient scene loading order.
 const ui=document.getElementById('ddSindenCountdownSetting');if(ui)ui.style.display='flex';
 ddSindenCountApply(ddSindenCountdownSeconds);
}
function ddSindenGateInit(s){
 const refereeDuel=!!duelScene(s)||(customScenes.length>=9&&customSceneIndex>=0&&customSceneIndex<8&&s?.sceneType!=='cutscene'&&!!s?.targets?.some(t=>t.enemyType==='shooter'));
 const active=refereeDuel&&!s?.hangman?.ropeObjectId&&!duelRefDead;
 ddSindenGate=active?{scene:s,seconds:ddSindenCountdownSeconds,startedAt:null,released:false,refEntryDelay:duelState?.referee?.entryDelay??0}:null;
 // Holster both mouse and Sinden on every referee-led duel. Start after the cinematic.
 ddSindenSafeLocked=active;ddSindenSafeAwaitReentry=false;ddSindenSafeCarry=false;
 ddSindenSafeScene=s;ddSindenSafeSceneStart=customSceneStart;
}
const ddSindenGatePrompt=document.createElement('div');
ddSindenGatePrompt.id='ddSindenGatePrompt';ddSindenGatePrompt.style.cssText='display:none;position:fixed;top:24%;left:50%;transform:translateX(-50%);color:#fff0d0;text-shadow:0 2px 6px #000;font:bold 16px Georgia,serif;letter-spacing:1px;z-index:19;pointer-events:none;text-align:center;background:#090e11bc;padding:8px 15px;border:1px solid #f3d49d66';
document.body.appendChild(ddSindenGatePrompt);
function ddSindenSafeStatus(){
 const live=mode==='custom'&&(state==='playing'||state==='cinematic'||state==='countdown');
 if(ddSindenSafeCarry&&live)return {active:true,released:false,carry:true};
 const sc=live&&!customExitTransition?customScenes[customSceneIndex]:null;
 const gate=ddSindenGate;
 if(!sc||!gate||gate.scene!==sc)return {active:false,released:true};
 return {active:true,released:gate.released};
}
function ddSindenSafeCenter(){return {x:innerWidth*.5,y:innerHeight*.88};}
function ddSindenSafeSync(){
 const sc=customScenes[customSceneIndex]||null;
 if(ddSindenSafeScene!==sc){ddSindenSafeScene=sc;ddSindenSafeSceneStart=customSceneStart;ddSindenSafeLocked=false;ddSindenSafeAwaitReentry=false;}
 const status=ddSindenSafeStatus(),gate=ddSindenGate;
 document.body.classList.toggle('ddSindenSafeActive',status.active&&!status.released);
 ddSindenSafeCircle.style.display=status.active&&!status.released?'flex':'none';
 ddSindenGatePrompt.style.display=status.active&&!status.released?'block':'none';
 if(status.carry){
  ddSindenSafeCircle.textContent='SAFE';ddSindenGatePrompt.textContent='GUN HOLSTERED · NEXT STAGE';
 }else if(status.active&&!status.released&&gate){
  const remaining=gate.startedAt==null?gate.seconds:Math.max(0,gate.seconds-(elapsed-gate.startedAt));
  ddSindenSafeCircle.textContent=gate.startedAt==null?'SAFE':String(Math.ceil(remaining));
  ddSindenGatePrompt.textContent=gate.startedAt==null?'GUN HOLSTERED · WAIT FOR CUTSCENE':`REFEREE ENTERS IN ${remaining.toFixed(1)}s`;
 }
 if(status.carry){ddSindenSafeLocked=true;ddSindenSafeAwaitReentry=false;}
 else if(!status.active){ddSindenSafeLocked=false;ddSindenSafeAwaitReentry=false;}
 else if(status.released&&ddSindenSafeLocked){ddSindenSafeLocked=false;ddSindenSafeAwaitReentry=true;}
 return status;
}
function ddSindenSafeMapped(x,y){
 const status=ddSindenSafeSync();if(!status.active)return {x,y};
 const center=ddSindenSafeCenter(),gate=ddSindenGate;
 if(status.carry)return center;
 if(!status.released){
  // Cinema and countdown are always holstered. A raw mouse/Sinden move cannot
  // raise the player arm, fire along a hidden ray, or start the timer early.
  ddSindenSafeLocked=true;
  return center;
 }
 // Keep the game crosshair at its last safe position during Sinden border-loss
 // pulses; release only after the gun's aim genuinely re-enters the viewport.
 if(ddSindenSafeAwaitReentry){
  const edge=x<=5||y<=5||x>=innerWidth-5||y>=innerHeight-5;
  if(edge)return center;
  ddSindenSafeAwaitReentry=false;
 }
 return {x,y};
}
function ddSindenGateHold(dt){
 const g=ddSindenGate,sc=customScenes[customSceneIndex];
 if(!g||g.scene!==sc||g.released||dt<=0)return false;
 // Deliberately start the REF ENTRY countdown on the first playable tick
 // AFTER a cinematic plays to the end or is skipped. The scene clock is paused.
 if(g.startedAt===null&&state==='playing'&&!DDCinematic.active)g.startedAt=elapsed;
 if(g.startedAt!==null&&elapsed-g.startedAt>=g.seconds){
  g.released=true;customSceneStart=elapsed;
  // Undo the artificial 9999-second hide; the referee may NOW step out.
  if(duelState?.referee)duelState.referee.entryDelay=Math.max(0,g.refEntryDelay||0);
  ddSindenSafeSync();return false;
 }
 // Author's scene clock and actor paths begin only once the referee may enter.
 customSceneStart=elapsed;
 if(duelState?.referee)duelState.referee.entryDelay=9999;
 ddSindenSafeSync();return true;
}
window.DDGameAimView=()=>{const st=ddSindenSafeStatus();return {x:aim.x/Math.max(1,innerWidth),y:aim.y/Math.max(1,innerHeight),holsterLocked:!!(st.active&&!st.released)};};
(function ddSindenSafeFrame(){
 const status=ddSindenSafeSync();
 if(status.active&&(ddSindenSafeLocked||ddSindenSafeAwaitReentry)){
  const p=ddSindenSafeCenter(),canvas=ddSindenInputXY(p.x,p.y);
  aim.x=canvas.x;aim.y=canvas.y;
  const cross=document.getElementById('crosshair');
  if(cross){cross.style.left=p.x+'px';cross.style.top=p.y+'px';}
 }
 requestAnimationFrame(ddSindenSafeFrame);
})();

