 function duelSample(force=false){const d=duelState;if(!d||!['waiting','draw'].includes(d.phase)||state!=='playing'||!d.recordTrail||!Number.isFinite(d.land))return;const ms=Math.round((elapsed-customSceneStart-d.land)*1000),a=d.trail.at(-1);if(!force&&a&&ms-a[0]<16)return;const x=aim.x/innerWidth,y=aim.y/innerHeight;if(a&&x===a[1]&&y===a[2]&&!force)return;d.trail.push([+ms.toFixed(2),+x.toFixed(5),+y.toFixed(5)]);if(a)d.travel+=Math.hypot((x-a[1])*d.viewW,(y-a[2])*d.viewH);}
