function duelReadChallenge(root){
 if(!root||root.format!==DUEL_CHALLENGE_FORMAT||!root.challenge)return null;
 const c=root.challenge;
 if(c.version!==1||!Array.isArray(c.stages)||c.stages.length>100||c.stages.length<1)throw Error('Challenge JSON has invalid stage records.');
 const safe=[];
 const validatePoint=(p,shots=false)=>Array.isArray(p)&&p.length>=3&&p.slice(0,3).every(Number.isFinite)&&p[0]>=-30000&&p[0]<=30000&&p[1]>=0&&p[1]<=1&&p[2]>=0&&p[2]<=1;
 for(const st of c.stages){
  if(!Number.isInteger(st.stage)||st.stage<1||st.stage>100||!Array.isArray(st.trail)||st.trail.length>6000||!Array.isArray(st.shotPoints)||st.shotPoints.length>300||!st.trail.every(p=>validatePoint(p))||!st.shotPoints.every(p=>validatePoint(p,true)))throw Error('Invalid challenge mouse-path or shot timestamps.');
  if(st.winningDrawMs!=null&&(!Number.isFinite(st.winningDrawMs)||st.winningDrawMs<0||st.winningDrawMs>30000))throw Error('Invalid challenge winning shot time.');
  safe.push({stage:st.stage,title:String(st.title||'').slice(0,80),stageEvents:(Array.isArray(st.stageEvents)?st.stageEvents:[]).filter(e=>e&&e.kind==='duel-draw'&&Number.isFinite(e.stageMs)).slice(0,2).map(e=>({kind:'duel-draw',stageMs:e.stageMs})),outcome:st.outcome==='win'?'win':'loss',deathStageMs:Number.isFinite(st.deathStageMs)&&st.deathStageMs>=0?st.deathStageMs:null,sourceDrawStageMs:Number.isFinite(st.sourceDrawStageMs)?st.sourceDrawStageMs:null,winningDrawMs:st.winningDrawMs??null,earlyDraw:!!st.earlyDraw,earlyLeadMs:Number.isFinite(st.earlyLeadMs)?st.earlyLeadMs:null,earlyShotCount:Number.isInteger(st.earlyShotCount)?st.earlyShotCount:0,
   neutralization:st.neutralization==='disarmed'?'disarmed':null,
   disarmEvents:(Array.isArray(st.disarmEvents)?st.disarmEvents:[]).filter(e=>e&&Number.isFinite(e.stageMs)&&e.stageMs>=0&&e.stageMs<=120000).slice(0,50).map(e=>({stageMs:e.stageMs,drawMs:Number.isFinite(e.drawMs)?e.drawMs:null,zone:String(e.zone||'gunhand').slice(0,40),weaponHand:e.weaponHand==='left'?'left':'right'})),
   hitEvents:(Array.isArray(st.hitEvents)&&st.hitEvents.length?st.hitEvents:(st.stageEvents||[]).filter(e=>e&&e.kind==='duel-opponent-hit').map(e=>({...e,stageMs:Number.isFinite(e.stageMs)?e.stageMs:Math.round((e.t||0)*1000)}))).filter(e=>e&&Number.isFinite(e.stageMs)&&e.stageMs>=0&&e.stageMs<=120000&&typeof e.zone==='string').slice(0,300).map(e=>({stageMs:e.stageMs,drawMs:Number.isFinite(e.drawMs)?e.drawMs:null,zone:e.zone,weaponHand:e.weaponHand==='left'?'left':'right',lethal:!!e.lethal,disarmed:!!e.disarmed,downed:!!(e.downed||/(?:left|right)(?:hip|thigh|knee|shin|ankle|foot)$/.test(e.zone)),x:Number.isFinite(e.x)?e.x:.5,y:Number.isFinite(e.y)?e.y:.5})),objectEvents:(Array.isArray(st.objectEvents)?st.objectEvents:[]).filter(e=>e&&Number.isInteger(e.objectId)&&e.objectId>0&&Number.isFinite(e.stageMs)&&e.stageMs>=0&&e.stageMs<=120000).slice(0,300).map(e=>({stageMs:e.stageMs,objectId:e.objectId,shattered:!!e.shattered,count:Math.max(1,Math.min(100,Number(e.count)||1)),point:Array.isArray(e.point)&&e.point.length===3&&e.point.every(v=>Number.isFinite(v)&&Math.abs(v)<10000)?e.point.slice(0,3):null})).sort((a,b)=>a.stageMs-b.stageMs),
   reloadEvents:(Array.isArray(st.reloadEvents)?st.reloadEvents:[]).filter(e=>e&&Number.isFinite(e.stageMs)&&e.stageMs>=0&&e.stageMs<=120000).slice(0,100).map(e=>({stageMs:e.stageMs})).sort((a,b)=>a.stageMs-b.stageMs),
   firstShotMs:Number.isFinite(st.firstShotMs)?st.firstShotMs:null,limitMs:Number.isFinite(st.limitMs)?st.limitMs:null,trail:st.trail.map(p=>p.slice(0,3)),shotPoints:st.shotPoints.map(p=>p.slice(0,3)),stageEvents:Array.isArray(st.stageEvents)?st.stageEvents.filter(e=>e&&typeof e.kind==='string'&&Number.isFinite(e.t)).slice(0,1500):[],
    refHits:Array.isArray(st.refHits)?st.refHits.filter(e=>e&&Number.isFinite(e.t)&&e.t>=0&&e.t<=60000&&/^(head|neck|heart|chest|abdomen|pelvis|(left|right)(shoulder|upperarm|elbow|forearm|wrist|hand|hip|thigh|knee|shin|ankle|foot))$/.test(e.zone)).slice(0,100).map(e=>({t:e.t,zone:e.zone})):[]});
 }
 return {gunslinger:String(c.gunslinger||'Unknown challenger').slice(0,30),reputation:String(c.reputation||'').slice(0,40),fogStage:Number.isInteger(c.fogStage)&&c.fogStage>=1&&c.fogStage<=100?c.fogStage:null,gallowsStartMs:Number.isFinite(c.gallowsStartMs)&&c.gallowsStartMs>=0&&c.gallowsStartMs<=120000?Math.round(c.gallowsStartMs):null,gallowsShots:Array.isArray(c.gallowsShots)?c.gallowsShots.filter(v=>v&&Number.isFinite(v.t)&&v.t>=0&&v.t<=120&&Number.isFinite(v.x)&&v.x>=0&&v.x<=1&&Number.isFinite(v.y)&&v.y>=0&&v.y<=1).slice(0,300):[],
 gallowsEvents:(Array.isArray(c.gallowsEvents)?c.gallowsEvents:[]).filter(e=>e&&['hangman-rope-cut','hangman-executioner-hit','duel-weapon-disarmed','cow-killer-hit'].includes(e.kind)&&Number.isFinite(e.stageMs)&&e.stageMs>=0&&e.stageMs<=120000).slice(0,300).map(e=>({kind:e.kind,stageMs:e.stageMs,zone:String(e.zone||''),lethal:!!e.lethal,disarmed:!!e.disarmed})).sort((a,b)=>a.stageMs-b.stageMs),stages:safe};
}
// Source and recipient may holster at different moments. The referee's
// actual leaf landing, rather than the import/start screen or holster delay,
// synchronizes reciprocal attacks while the referee is alive.
function duelRecordedDrawStageMs(track){
 if(!track)return null;
 if(Number.isFinite(track.sourceDrawStageMs))return track.sourceDrawStageMs;
 for(const e of track.disarmEvents||[])if(Number.isFinite(e.stageMs)&&Number.isFinite(e.drawMs))return e.stageMs-e.drawMs;
 for(const e of track.hitEvents||[])if(Number.isFinite(e.stageMs)&&Number.isFinite(e.drawMs))return e.stageMs-e.drawMs;
 const timeline=track.stageEvents||[];
 const draw=timeline.find(e=>e.kind==='duel-draw'&&Number.isFinite(e.stageMs));
 return draw?.stageMs??null;
}
function duelGhostMappedStageTime(d,sourceStageMs){
 if(!Number.isFinite(sourceStageMs))return Infinity;
 // With a dead referee, nobody can stall ghost attacks by refusing to ready.
 if(d.refereeDead)return sourceStageMs;
 if(!d.holstered||!Number.isFinite(d.land))return Infinity;
 const sourceDraw=duelRecordedDrawStageMs(d.ghostTrack);
 return Number.isFinite(sourceDraw)?sourceStageMs+(d.land*1000-sourceDraw):sourceStageMs;
}
function duelGhostPosition(d,ms){
 const a=d.ghostTrack?.trail||[];
 if(!a.length)return {x:.5,y:1};
 if(ms<=a[0][0])return {x:a[0][1],y:a[0][2]};
 let left=0,right=a.length-1;
 while(left<right){const k=(left+right)>>1;if(a[k][0]<ms)left=k+1;else right=k;}
 const curr=a[left],prev=a[Math.max(0,left-1)];
 const f=clamp((ms-prev[0])/Math.max(1,curr[0]-prev[0]),0,1);
 return {x:mix(prev[1],curr[1],f),y:mix(prev[2],curr[2],f)};
}

const DD_GHOST_GUNSHOT_SRC='data:audio/wav;base64,';
function ddPlayGhostGunshot(){if(!cfg.sounds)return;try{const a=new Audio(DD_GHOST_GUNSHOT_SRC);a.volume=.72;a.play().catch(()=>{});}catch(_){}}
// Same muffled asset used by AI opponents. Keep a small voice pool so rapid
// Town Drunk/Bounty Hunter/executioner shots can overlap without creating
// a fresh Audio instance every frame. Player 1's ghost remains a separate route.
let ddAiGunVoices=null,ddAiGunVoiceCursor=0;
function ddPlayAIGunshot(){
 if(!cfg.sounds)return;
 try{
  if(!ddAiGunVoices)ddAiGunVoices=Array.from({length:5},()=>{const a=new Audio(DD_GHOST_GUNSHOT_SRC);a.volume=.72;return a;});
  const a=ddAiGunVoices.find(v=>v.paused||v.ended)||ddAiGunVoices[(ddAiGunVoiceCursor++)%ddAiGunVoices.length];
  a.pause();a.currentTime=0;
  const played=a.play();if(played&&played.catch)played.catch(()=>{});
 }catch(_e){}
}
function ddPlayGhostReload(){if(!cfg.sounds)return;ddPlayCylinderSpin();}

function duelGhostTick(d){
 if(!d.ghostTrack||!d.enemy||!['draw','waiting'].includes(d.phase))return;
 const currentStageMs=Math.max(0,Math.round((elapsed-customSceneStart)*1000));
 const sourceDraw=duelRecordedDrawStageMs(d.ghostTrack);
 // Recorded shotPoints are draw-relative; all event queues are compared on a single stage clock.
 const shots=d.ghostTrack.shotPoints||[];
 while(d.ghostShotCursor<shots.length){
  const shot=shots[d.ghostShotCursor];
  const originalStageMs=(Number.isFinite(sourceDraw)?sourceDraw:0)+shot[0];
  const mapped=duelGhostMappedStageTime(d,originalStageMs);
  if(mapped>currentStageMs)break;
  d.ghostShotCursor++;
  if(Number.isFinite(d.ghostTrack.deathStageMs)&&originalStageMs>d.ghostTrack.deathStageMs)continue;
  d.enemy.shooterFlash=.18;run.shooterShots++;ddPlayGhostGunshot();
  run.events.push({kind:'duel-ghost-shot',scene:customSceneIndex+1,stageMs:currentStageMs,ghostMs:shot[0],aimX:shot[1],aimY:shot[2],source:'ghost'});
 }
 // Show every recorded reload, even when Player 2 has chosen different cinematics.
 const reloads=d.ghostTrack.reloadEvents||[];
 while(d.ghostReloadCursor<reloads.length&&duelGhostMappedStageTime(d,reloads[d.ghostReloadCursor].stageMs)<=currentStageMs){
  const ev=reloads[d.ghostReloadCursor++];ddPlayGhostReload();
  run.events.push({kind:'ghost-reload',scene:customSceneIndex+1,stageMs:currentStageMs,sourceStageMs:ev.stageMs,source:'ghost'});
 }
 // Bullet damage to scenery is visual-state data, not merely an aim-trail effect.
 const objects=d.ghostTrack.objectEvents||[];
 while(d.ghostObjectCursor<objects.length&&duelGhostMappedStageTime(d,objects[d.ghostObjectCursor].stageMs)<=currentStageMs){
  const ev=objects[d.ghostObjectCursor++],obj=customScenes[customSceneIndex]?.objects?.find(o=>o.id===ev.objectId);
  if(!obj||customBrokenObjects.has(obj.id))continue;
  const pt=ev.point||[d.enemy.x||0,1,d.enemy.z||-5];
  const result=customShotObject(obj,pt);
  snd('object');
  run.events.push({kind:'ghost-object-impact',scene:customSceneIndex+1,stageMs:currentStageMs,sourceStageMs:ev.stageMs,objectId:obj.id,shattered:!!result.shattered,source:'ghost'});
 }
 // Disarm is authoritative; the opponent's weapon state must not cancel the hit to Player 2.
 const ghostDisarms=d.ghostTrack.disarmEvents||[];
 while(d.ghostDisarmCursor<ghostDisarms.length&&duelGhostMappedStageTime(d,ghostDisarms[d.ghostDisarmCursor].stageMs)<=currentStageMs){
  const ev=ghostDisarms[d.ghostDisarmCursor++];
  if(d.playerDisarmed)continue;
  d.playerDisarmed=true;gun.rounds=0;gun.reloading=0;window.DDWesternGunArm?.flyOff?.();
  run.events.push({kind:'ghost-disarmed-player',scene:customSceneIndex+1,stageMs:currentStageMs,zone:ev.zone,weaponHand:ev.weaponHand||'right',sourceStageMs:ev.stageMs});
  showNote('GHOST HIT YOUR GUN HAND · DISARMED','#ffc28b');
 }
 const ghostHits=d.ghostTrack.hitEvents||[];
 while(d.ghostHitCursor<ghostHits.length&&duelGhostMappedStageTime(d,ghostHits[d.ghostHitCursor].stageMs)<=currentStageMs){
  const hit=ghostHits[d.ghostHitCursor++];
  run.events.push({kind:'ghost-recorded-hit',scene:customSceneIndex+1,stageMs:currentStageMs,zone:hit.zone,weaponHand:hit.weaponHand||'right',lethal:!!hit.lethal,downed:!!hit.downed,disarmed:!!hit.disarmed,sourceStageMs:hit.stageMs});
  if(hit.disarmed&&!d.playerDisarmed){d.playerDisarmed=true;gun.rounds=0;gun.reloading=0;window.DDWesternGunArm?.flyOff?.();showNote('GHOST HIT YOUR GUN HAND · DISARMED','#ffc28b');}
  if(hit.downed||/leg|thigh|knee|shin|hip|ankle|foot/i.test(hit.zone)){
   westernCameraImpact(false);if(westernHitFall)westernHitFall.persistent=true;
   customCoverViewY=Math.min(customCoverViewY,.98);
  }
  if(hit.lethal){duelLose('GHOST FATAL HIT · '+String(hit.zone||'UNKNOWN').toUpperCase());return;}
 }
 if(d.phase==='waiting'&&d.refereeDead&&d.ghostTrack.earlyDraw&&Number.isFinite(d.ghostTrack.earlyLeadMs)){
  const mapped=duelGhostMappedStageTime(d,(sourceDraw??0)-d.ghostTrack.earlyLeadMs);
  if(currentStageMs>=mapped){duelLose('EARLY GHOST DRAW · '+duelChallenge.gunslinger.toUpperCase());return;}
 }
 if(d.phase==='draw'&&d.ghostTrack.neutralization!=='disarmed'&&Number.isFinite(d.ghostTrack.winningDrawMs)){
  const mapped=duelGhostMappedStageTime(d,(sourceDraw??0)+d.ghostTrack.winningDrawMs);
  if(currentStageMs>=mapped)duelLose('OUTDRAWN BY '+duelChallenge.gunslinger.toUpperCase());
 }
}
function duelBuildChallenge(){
 if(!run?.duelStages?.length)return;
 const rows=run.duelStages;
 const stages=rows.map(st=>({
  stage:st.stage,title:st.title,outcome:st.outcome,cheaterDraw:!!st.cheaterDraw,lossReason:st.reason||null,livesSpent:st.livesSpent||0,deathStageMs:st.deathStageMs??null,sourceDrawStageMs:Number.isFinite(st.drawStageMs)?st.drawStageMs:null,stageSyncMs:0,
  playerRole:'opponent',stageEvents:(run.events||[]).filter(e=>(e.stage===st.stage||e.scene===st.stage)&&/duel|referee|shot|hit|draw|holster|injury|wound|disarm/i.test(e.kind||'')).slice(0,1500),
  limitMs:st.limitMs,firstShotMs:st.firstShotMs,winningDrawMs:st.winningDrawMs,earlyDraw:!!st.earlyDraw,earlyLeadMs:st.earlyLeadMs,
  earlyShotCount:st.earlyShotCount||0,neutralization:st.neutralization||null,
  objectEvents:(run.events||[]).filter(e=>e.scene===st.stage&&e.source==='player'&&['custom-object-hit','custom-object-shattered'].includes(e.kind)&&Number.isFinite(e.stageMs)).slice(0,300).map(e=>({stageMs:e.stageMs,objectId:e.objectId,count:e.count,shattered:e.shattered,point:e.point})),
  reloadEvents:(run.events||[]).filter(e=>e.scene===st.stage&&e.kind==='instant-reload'&&Number.isFinite(e.stageMs)).slice(0,100).map(e=>({stageMs:e.stageMs})),
  disarmEvents:(st.disarmEvents||[]).filter(e=>st.deathStageMs==null||e.stageMs<=st.deathStageMs).slice(0,50),hitEvents:(st.hitEvents||[]).filter(e=>st.deathStageMs==null||e.stageMs<=st.deathStageMs).slice(0,300),refHits:(st.refHits||[]).filter(e=>st.deathStageMs==null||e.t<=st.deathStageMs).slice(0,100),
  // The path moves the opponent's gun arm; shotPoints cue its muzzle flashes.
  trail:(st.trail||[]).filter((p,i,a)=>i%Math.max(1,Math.ceil(a.length/6000))===0||i===a.length-1).map(p=>p.slice(0,3)),
  shotPoints:(st.shotPoints||[]).slice(0,300).map(p=>p.slice(0,3))
 }));
 const pkg={format:DUEL_CHALLENGE_FORMAT,title:'Mercy\'s End · Gunslinger Challenge',
  assetPackId:'dead-mans-draw-9scene',assets:'use-installed-local-scene-json',lightweight:true,challenge:{version:1,gunslinger:duelPlayerName,reputation:DUEL_PACES[duelSelectedTier]?.name||'Trail Hand',created:new Date().toISOString(),fogStage:run.fogStage||null,playerRole:'opponent',stageTimelineClock:'stage-start',stageSyncVersion:2,cowKillerEventsVersion:2,gallowsOutcome:run.gallowsOutcome||null,gallowsVictimFate:run.gallowsVictimFate||null,gallowsExecutionerResolved:!!run.gallowsExecutionerResolved,gallowsPlayerKilled:!!run.gallowsPlayerKilled,gallowsCowKillerFate:run.gallowsCowKillerFate||null,livesSpent:run.livesSpent||0,stageLifeLosses:(run.stageLifeLosses||[]).slice(),gallowsStartMs:Number.isFinite(run.gallowsStartMs)?run.gallowsStartMs:Math.round(Math.max(0,Number(customScenes.find(sc=>!!sc?.hangman?.ropeObjectId)?.hangman?.leafDropSeconds)||2.25)*1000),gallowsShots:(run.gallowsShots||[]).slice(0,300),
   gallowsEvents:(run.events||[]).filter(e=>e.scene===customScenes.length&&e.source!=='ghost'&&['hangman-rope-cut','hangman-executioner-hit','duel-weapon-disarmed','cow-killer-hit'].includes(e.kind)&&Number.isFinite(e.stageMs)).slice(0,300).map(e=>({kind:e.kind,stageMs:e.stageMs,zone:e.zone||null,lethal:!!e.lethal,severJoint:e.severJoint||null,detachedPart:e.detachedPart||null,disarmed:!!e.disarmed})),stageShotTimes:run.stageShotTimes||{},stages},
  instructions:'Import this JSON into the compatible Dead Man\'s Draw player. Choose Ghost Draw for recorded arm movement and shot times, or Classic Challenge for AI timing and score comparison. Scenes remain editable in Motion Studio.'};
 pkg.instructions='Load the same nine-scene JSON locally in your 3D Player, then import this compact challenge as the ghost. Contains complete shot/aim/timing/injury/referee/object records; no GLBs, textures or videos.';
 return pkg;
}
