 const sceneMs=Math.max(0,Math.round((elapsed-customSceneStart)*1000));
 const isLimb=/^(left|right)(shoulder|upperarm|elbow|forearm|wrist|hand|hip|thigh|knee|shin|ankle|foot)$/.test(zone);
 const fatalZone=['head','neck','heart'].includes(zone);
