  if(count<rule.count||(rule.waitForPathEnd&&t<e.customEnd))continue;
  e.customPostState=rule.mode;e.customPostAt=elapsed;e.customHoldAt=clamp(e.customAttackProgress??t,e.customStart,e.customEnd);
  run.events.push({t:+elapsed.toFixed(3),kind:'custom-post-attack-'+rule.mode,target:e.customCombatId,scene:waveIndex,count});
  if(rule.mode==='die'){e.customPostResolved=true;e.entryDelay=0;makeRagdoll(e,livePose(e),'chest',.8);showNote('AUTO DEATH · TARGET '+e.customCombatId,'#b8dbcd');}
