 box(streetFace,y-height*.09,z-depth*.18,width*.19,height*.28,depth*.18,shadow);
 for(const offset of [-.16,.12]){
  box(streetFace,y+height*(.14+offset),z+depth*(offset*.9),width*.14,height*.12,depth*.17,[.12,.16,.19]);
  box(streetFace,y+height*(.14+offset),z+depth*(offset*.9),width*.16,height*.14,depth*.03,trim);
 }
 const edge=.022;
 limb([streetFace,y-height*.48,z-depth*.48],[streetFace,y+height*.48,z-depth*.48],edge,trim);
