 if(e.rubbleClimbing){e.rubbleAge+=dt;if(e.rubbleAge>=.85){e.rubbleClimbing=false;run.rubbleCrossings++;run.events.push({t:+elapsed.toFixed(3),kind:'rubble-climb-cleared',enemy:e.type});}else continue;}
 // Do not cross the contact threshold before an overt and readable wind-up.
 const distToPlayer=Math.abs(cam.z-e.z);
