 for(const sx of [-.84,.84])limb([x+sx,.30,z-.48],[x+sx,.30,z+.48],.022,[.20,.20,.19]);   // side rails low
 for(const sx of [-.75,.75])for(const sz of [-.48,.48])orb([x+sx,.06,z+sz],.05,[.08,.08,.08]); // castors
 for(const sx of [-.84,.84])box(x+sx,.60,z,.04,.06,1.0,[.21,.2,.19]);
