  for(let i=0;i<(DDGraphics.preset==='performance'?1:2);i++){ps3Pass(1,PS3.bloomA,PS3.bloomB,[1,0]);ps3Pass(1,PS3.bloomB,PS3.bloomA,[0,1])}
